//! Platform-neutral data models.
//! (Generated by v0.6.0 Step 3 Phase 1)
//!
//! Single source of truth for the structs every platform backend (GitHub,
//! Gitea, GitLab) populates and every view renders. [`crate::github::models`]
//! re-exports them for backward compatibility.
//!
//! Keeping them out of the octocrab type graph lets the panels render without
//! depending on octocrab's enum variants.

/// One pull request row in the list panel.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct PrSummary {
    pub number: u64,
    pub title: String,
    pub state: String,
    pub draft: bool,
    pub author: String,
    pub head_ref: String,
    pub base_ref: String,
    /// ISO-8601 `updated_at`; kept raw until the UI learns relative time.
    pub updated_at: String,
}

/// Detail of a pull request, including its head-commit checks.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct PrDetail {
    /// Core summary fields reused verbatim by the detail panel.
    pub summary: PrSummary,
    /// Markdown body (possibly empty).
    pub body: String,
    /// PR labels (names); empty when the PR has none.
    pub labels: Vec<String>,
    /// Mergeability: `None` means the platform has not computed it yet.
    pub mergeable: Option<bool>,
    /// Check runs for the head commit.
    pub checks: Vec<CheckSummary>,
}

/// One CI check run for a commit.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CheckSummary {
    pub name: String,
    /// `queued` / `in_progress` / `completed` / `unknown`.
    pub status: String,
    /// `success` / `failure` / `neutral` / `cancelled` / `skipped` / `unknown`.
    pub conclusion: String,
    pub html_url: String,
}

/// One issue row in the issues panel.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct IssueSummary {
    pub number: u64,
    pub title: String,
    pub state: String,
    pub author: String,
    /// Assignee login; `None` when unassigned.
    pub assignee: Option<String>,
    pub updated_at: String,
    /// Label names; empty when the issue has none.
    pub labels: Vec<String>,
}

/// Detail of an issue, fetched by `get_issue`.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct IssueDetail {
    /// Core issue fields reused verbatim by the detail panel.
    pub summary: IssueSummary,
    /// Markdown body (possibly empty).
    pub body: String,
}

/// One notification row (repo-filtered to the current repo).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct NotificationSummary {
    /// Opaque platform notification/todo id.
    pub id: String,
    /// `owner/repo` of the repository the notification belongs to.
    pub repo: String,
    pub subject_title: String,
    /// `PullRequest` / `Issue` / `CheckSuite` / `Commit` / `Release` / `unknown`.
    pub subject_type: String,
    pub reason: String,
    pub updated_at: String,
    pub unread: bool,
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn pr_detail_carries_labels() {
        let d = PrDetail {
            summary: PrSummary {
                number: 1,
                title: "t".to_string(),
                state: "open".to_string(),
                draft: false,
                author: "a".to_string(),
                head_ref: "h".to_string(),
                base_ref: "b".to_string(),
                updated_at: String::new(),
            },
            body: String::new(),
            labels: vec!["bug".to_string()],
            mergeable: None,
            checks: Vec::new(),
        };
        assert_eq!(d.labels, vec!["bug".to_string()]);
    }

    #[test]
    fn issue_summary_and_detail_carry_assignee_and_body() {
        let base = IssueSummary {
            number: 2,
            title: "t".to_string(),
            state: "open".to_string(),
            author: "a".to_string(),
            assignee: None,
            updated_at: String::new(),
            labels: Vec::new(),
        };
        assert_eq!(base.assignee, None);
        let assigned = IssueSummary {
            assignee: Some("bob".to_string()),
            ..base.clone()
        };
        assert_eq!(assigned.assignee.as_deref(), Some("bob"));
        let d = IssueDetail {
            summary: assigned,
            body: "text".to_string(),
        };
        assert_eq!(d.body, "text");
    }
}
